


import React, { useEffect, useState } from "react";
import { Home, Calendar, ChevronDown } from "lucide-react";
import { Link, useLocation } from "react-router-dom";
import { MapPin } from "lucide-react";

export const Sidebar = ({ isSidebarOpen = true, setIsSidebarOpen = () => {} }) => {
  const location = useLocation();
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [openSubmenu, setOpenSubmenu] = useState(null); // dynamically track open menu

  const menuItems = [
    { icon: <Home size={24} />, label: "Dashboard", path: "/Dashboard" },
  
    {
      icon: <Calendar size={24} />,
      label: "Master",
      subItems: [
       
         { label: "Location Service", path: "/PincodeManager" },
     
        { label: "Crop Category", path: "/CropCategoryPage" },
        { label: "Crop Stage", path: "/CropStages" },
            { label: "Crop", path: "/Crop" },
             { label: "User", path: "/User" },
         ],
    },
  ];

  useEffect(() => {
    if (window.innerWidth < 768) {
      setIsSidebarOpen(false);
    }

    const prefersDark = window.matchMedia("(prefers-color-scheme: dark)").matches;
    setIsDarkMode(prefersDark);

    // Automatically open submenu if current path matches any subpath
    const openMenu = menuItems.find(
      (item) =>
        item.subItems &&
        item.subItems.some((sub) => location.pathname.startsWith(sub.path))
    );
    setOpenSubmenu(openMenu?.label || null);
  }, [location.pathname]);

  return (
    <>
      {isSidebarOpen && (
        <div
          className="fixed inset-0 bg-black bg-opacity-30 z-40 md:hidden"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      <div
        className={`fixed top-0 left-0 h-full z-50 transition-all duration-300 shadow-lg ${
          isSidebarOpen ? "w-64" : "w-16"
        } ${isDarkMode ? "bg-gray-900 text-white" : "bg-white text-gray-900"}`}
      >
        <div className="flex items-center justify-between p-4 border-b border-opacity-20">
          {isSidebarOpen && (
            <h2 className="text-xl font-bold text-indigo-600">Dashboard</h2>
          )}
        </div>

        <div className="flex flex-col h-full justify-between pt-4">
          <nav className="px-2 space-y-1">
            {menuItems.map(({ icon, label, path, subItems }) => {
              const isActive =
                location.pathname === path ||
                (subItems && subItems.some((sub) => location.pathname === sub.path));
              const isSubmenuOpen = openSubmenu === label;

              return (
                <div key={label}>
                  {subItems ? (
                    <>
                      <div
                        className={`flex items-center px-3 py-2 rounded-md cursor-pointer transition-colors ${
                          isActive
                            ? isDarkMode
                              ? "bg-gray-700 text-white"
                              : "bg-blue-100 text-blue-900"
                            : "hover:bg-gray-200 hover:text-blue-800"
                        }`}
                        onClick={() =>
                          setOpenSubmenu((prev) => (prev === label ? null : label))
                        }
                      >
                        <span className="mr-3">{icon}</span>
                        {isSidebarOpen && (
                          <div className="flex justify-between items-center w-full">
                            <span className="text-sm font-medium">{label}</span>
                            <ChevronDown
                              size={16}
                              className={`ml-2 transition-transform duration-200 ${
                                isSubmenuOpen ? "rotate-180" : ""
                              }`}
                            />
                          </div>
                        )}
                      </div>
                      {isSidebarOpen && isSubmenuOpen && (
                        <div className="ml-8 mt-1 space-y-1">
                          {subItems.map(({ label: subLabel, path: subPath }) => (
                            <Link to={subPath} key={subLabel}>
                              <div
                                className={`px-3 py-2 text-sm rounded-md transition-all ${
                                  location.pathname === subPath
                                    ? "bg-blue-100 text-blue-900"
                                    : "hover:bg-gray-200 text-gray-700"
                                }`}
                              >
                                {subLabel}
                              </div>
                            </Link>
                          ))}
                        </div>
                      )}
                    </>
                  ) : (
                    <Link to={path}>
                      <div
                        className={`flex items-center px-3 py-2 rounded-md transition-colors ${
                          isActive
                            ? isDarkMode
                              ? "bg-gray-700 text-white"
                              : "bg-blue-100 text-blue-900"
                            : "hover:bg-gray-200 hover:text-blue-800"
                        }`}
                      >
                        <span className="mr-3">{icon}</span>
                        {isSidebarOpen && (
                          <span className="text-sm font-medium">{label}</span>
                        )}
                      </div>
                    </Link>
                  )}
                </div>
              );
            })}
          </nav>

          {/* <div className="absolute bottom-4 w-full px-3">
            <div
              className={`flex items-center px-3 py-2 rounded-lg ${
                isDarkMode
                  ? "bg-gray-800 text-gray-300 hover:bg-gray-700"
                  : "bg-gray-200 text-gray-700 hover:bg-gray-300"
              }`}
            >
              <span className="text-xs font-semibold">KD</span>
              {isSidebarOpen && (
                <>
                  <span className="ml-3 text-sm">Ketan's Studio</span>
                  <span className="ml-auto text-xs text-gray-500">
                    koriquam@gmail.com
                  </span>
                </>
              )}
            </div>
          </div> */}
        </div>
      </div>
    </>
  );
};
